private void HandleProceduralAiming()
{
    if (_upperBodyBone == null) return;

    // Force the upper body to look at the target, overriding the animation's rotation.
    // We use the ground position logic to get a horizontal look direction, 
    // but for vertical aiming (looking up/down), we might want to use AimPosition directly.
    // For Top-Down, usually horizontal rotation is key.

    Vector3 targetPoint = _aiming.AimPosition;
    // Ensure we look at the target at the same height as the bone to avoid weird tilting
    // unless you WANT the character to lean forward/back. 
    // For pure Top-Down "Turret" feel, flatten the Y.
    targetPoint.y = _upperBodyBone.position.y; 

    Vector3 aimDir = (targetPoint - _upperBodyBone.position).normalized;
    if (aimDir.sqrMagnitude > 0.001f)
    {
        Quaternion targetRotation = Quaternion.LookRotation(aimDir);
        // Apply offset (useful if the bone's 'forward' is different from model's forward)
        _upperBodyBone.rotation = targetRotation * Quaternion.Euler(_upperBodyOffset);
    }
}

